import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.wGDfT7ie.js";const h=JSON.parse('{"title":"First-time setup (live app)","description":"","frontmatter":{},"headers":[],"relativePath":"guide-first-time-setup.md","filePath":"guide-first-time-setup.md"}'),n={name:"guide-first-time-setup.md"};function s(i,e,l,p,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="first-time-setup-live-app" tabindex="-1">First-time setup (live app) <a class="header-anchor" href="#first-time-setup-live-app" aria-label="Permalink to &quot;First-time setup (live app)&quot;">​</a></h1><p>Use the <strong>live app</strong> at <a href="https://zkde.fi" target="_blank" rel="noreferrer">zkde.fi</a> — no local setup required.</p><h2 id="wallet" tabindex="-1">Wallet <a class="header-anchor" href="#wallet" aria-label="Permalink to &quot;Wallet&quot;">​</a></h2><p>Choose a Starknet wallet that supports Sepolia testnet:</p><ul><li><strong>ArgentX</strong> — <a href="https://www.argent.xyz/argent-x/" target="_blank" rel="noreferrer">argent.xyz/argent-x</a></li><li><strong>Braavos</strong> — <a href="https://braavos.app/" target="_blank" rel="noreferrer">braavos.app</a></li></ul><p>Install the extension, create or import a wallet, and switch the network to <strong>Starknet Sepolia</strong> in the wallet settings.</p><h2 id="testnet-funds" tabindex="-1">Testnet funds <a class="header-anchor" href="#testnet-funds" aria-label="Permalink to &quot;Testnet funds&quot;">​</a></h2><p>zkde.fi runs on <strong>Starknet Sepolia</strong>. You may need:</p><ul><li><strong>ETH</strong> — for gas (transaction fees)</li><li><strong>STRK</strong> — for some actions (e.g. Deploy to Ekubo)</li></ul><p>Get testnet tokens from a Sepolia faucet or via the app if a swap/faucet is available. Without funds, you can still connect and browse; transactions will fail until you have gas.</p><h2 id="connect-at-zkde-fi" tabindex="-1">Connect at zkde.fi <a class="header-anchor" href="#connect-at-zkde-fi" aria-label="Permalink to &quot;Connect at zkde.fi&quot;">​</a></h2><ol><li>Open <a href="https://zkde.fi" target="_blank" rel="noreferrer">zkde.fi</a>.</li><li>Click <strong>Connect</strong> (top right or in the hero).</li><li>Select your wallet (ArgentX or Braavos) and approve the connection.</li><li>Your address appears when connected; you can disconnect anytime.</li></ol><h2 id="after-connect" tabindex="-1">After connect <a class="header-anchor" href="#after-connect" aria-label="Permalink to &quot;After connect&quot;">​</a></h2><ul><li><strong>Landing</strong> — You’ll see the main value prop and links. Use the nav or buttons to go to <strong>Agent</strong> or <strong>Profile</strong>.</li><li><strong>Agent</strong> — Main workspace: Deploy to Ekubo, pools, DEX, rebalancer, session keys, compliance. See <a href="/docs/agent-dashboard.html">Agent dashboard</a> and <a href="/docs/guide-deploy-to-ekubo.html">Deploy to Ekubo</a>.</li><li><strong>Profile</strong> — Your reputation, collateral, relayer status, Risk Passport, linked addresses, compliance. See <a href="/docs/profile-and-identity.html">Profile and identity</a> and <a href="/docs/reputation-system.html">Reputation system</a>.</li></ul><p>Next: <a href="/docs/quick-start.html">Quick start (live app)</a> | <a href="/docs/agent-dashboard.html">Agent dashboard</a> | <a href="/docs/guide-deploy-to-ekubo.html">Deploy to Ekubo guide</a></p>',15)])])}const f=t(n,[["render",s]]);export{h as __pageData,f as default};
